import json, sys, time
sys.path.insert(0, '/workspace/dev')
import gen, ref, harness

def check(req, label, policy=False):
    got, proc = harness.run_request(req, policy=policy)
    want = ref.run(req)
    if got != want:
        print('MISMATCH', label)
        gs, ws = got.get('sessions'), want['sessions']
        if gs is None:
            print('  got:', json.dumps(got)[:400]); return False
        for i, (a, b) in enumerate(zip(gs, ws)):
            if a != b:
                for k in ('nodes', 'templates'):
                    if a[k] != b[k]: print('  session', i, k, a[k], b[k])
                if a['initial'] != b['initial']:
                    print('  session', i, 'initial\n   got ', json.dumps(a['initial'])[:800], '\n   want', json.dumps(b['initial'])[:800])
                for j, (x, y) in enumerate(zip(a['transactions'], b['transactions'])):
                    if x != y:
                        print('  session', i, 'tx', j, json.dumps(req['sessions'][i]['transactions'][j])[:500])
                        print('   got ', json.dumps(x)[:800])
                        print('   want', json.dumps(y)[:800])
                        for k in x:
                            if x[k] != y[k] and k == 'certificate':
                                for part in ('totals', 'groups', 'nodes', 'tasks'):
                                    if x[k][part] != y[k][part]:
                                        print('    part', part, json.dumps(x[k][part])[:300], '!=', json.dumps(y[k][part])[:300])
                        break
                break
        return False
    return True

def main():
    lo, hi = int(sys.argv[1]), int(sys.argv[2])
    ntx = int(sys.argv[3]) if len(sys.argv) > 3 else 12
    stale = float(sys.argv[4]) if len(sys.argv) > 4 else 0.25
    maxe = int(sys.argv[5]) if len(sys.argv) > 5 else 6
    bad = 0
    t0 = time.time()
    for seed in range(lo, hi):
        req = gen.gen_request(seed, sessions=(seed % 3) + 1, ntx=ntx, stale_prob=stale, max_edits=maxe)
        if not check(req, 'seed%d' % seed):
            bad += 1
            open('/workspace/dev/fail-%d.json' % seed, 'w').write(json.dumps(req))
            if bad > 2: break
    print('seeds %d..%d ntx=%d stale=%.2f maxedits=%d failures=%d (%.1fs)' % (lo, hi, ntx, stale, maxe, bad, time.time()-t0))

main()
PYEOF
